import {SPECIES} from './data.js';
import {catchArt} from './art.js';
import {catchChoice,catchBulkActions,settlementSummary} from './session-ui.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function sessionCheckout(game,limit=24){
 const nl=game.state.settings.language==='nl',rows=game.sessionRows('checkout').filter(f=>f.available),last=game.state.lastSession;
 const number=(n,d=0)=>new Intl.NumberFormat(nl?'nl-NL':'en-GB',{maximumFractionDigits:d}).format(n||0);
 const t=nl?{eye:'DE LIJNEN ZIJN BINNEN',intro:'Geef je vangsten een bestemming. Verkopen staat alvast geselecteerd; jij bevestigt wat er gebeurt.',empty:'Alles is afgehandeld',emptyNote:'Er wachten geen vissen meer op een keuze. Je ongebruikte voorraad en vispas blijven behouden.',caught:'Gevangen',waiting:'Nog te kiezen',weight:'Totaal gewicht',fish:'Vangst',value:'Waarde',choice:'Bestemming',more:'Meer vangsten tonen',done:'Terug naar de waterkant'}:{eye:'LINES OUT OF THE WATER',intro:'Choose a destination for your catches. Selling is preselected; nothing happens until you confirm.',empty:'All catches are settled',emptyNote:'No fish are waiting for a decision. Your unused supplies and fishing permit are kept.',caught:'Caught',waiting:'To settle',weight:'Total weight',fish:'Catch',value:'Value',choice:'Destination',more:'Show more catches',done:'Back to the water'};
 return `<section class="trip-checkout" data-session-checkout><div class="trip-checkout-intro" data-no-translate><span class="eyebrow">${t.eye}</span><p>${rows.length?t.intro:t.emptyNote}</p></div><div class="trip-checkout-metrics" data-no-translate><div><span>${t.caught}</span><b>${number(last?.caught||rows.length)}</b></div><div><span>${t.waiting}</span><b>${number(rows.length)}</b></div><div><span>${t.weight}</span><b>${number(last?.weight||rows.reduce((n,f)=>n+f.weight,0),2)} kg</b></div></div>${rows.length?`${catchBulkActions(game,rows)}<div class="trip-checkout-list"><table class="data-table"><thead data-no-translate><tr><th>${t.fish}</th><th>${t.value}</th><th>${t.choice}</th></tr></thead><tbody>${rows.slice(0,limit).map(f=>`<tr data-choice="${esc(f.choice||'')}"><td><div class="fish-name-cell">${catchArt(SPECIES.find(s=>s.id===f.species))}<div><strong>${esc(f.name)}</strong><small>${number(f.weight,2)} kg${f.trophy?' · ✧':''}</small></div></div></td><td>€ ${number(f.value,2)}</td><td>${catchChoice(game,f)}</td></tr>`).join('')}</tbody></table></div>${rows.length>limit?`<button class="button trip-checkout-more" data-action="more-checkout-catches" data-no-translate>${t.more} · ${number(Math.min(limit,rows.length))} / ${number(rows.length)}</button>`:''}<div class="settlement-bar" id="checkout-modal-summary">${settlementSummary(game,'checkout')}</div>`:`<div class="trip-checkout-empty" data-no-translate><span aria-hidden="true">✓</span><h3>${t.empty}</h3><button class="primary" data-action="close-checkout">${t.done}</button></div>`}</section>`;
}
